-- result 8JG8 (id 107): \bigl\{ (\psi^j)^* : 0 \le j < o \bigr\}  ->  \left\{ (\psi^j)^* \;\middle|\; j \in \Z,\ 0 \le j < o \right\}
INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '107', 1, 'set-notation-2026-11-24', '{"tag":"8JG8","type":"definition","title":"Cyclic family and weighted sum","section_id":102,"position":2,"listed":1,"statement_tex":"Let $\\psi$ be a \\hyperref[8JH4]{primitive character} of \\hyperref[8JA9]{order} $o$, and let\n\\[ \\mathcal C_\\psi = \\bigl\\{ (\\psi^j)^* : 0 \\le j < o \\bigr\\} \\]\nbe the set of primitive characters \\hyperref[8JB2]{inducing} its powers. It contains $\\mathbf 1$ and $\\psi$ and is closed under $\\chi \\mapsto \\bar\\chi$. With the weights\n\\[ a_{\\mathbf 1} = 1, \\qquad a_\\chi = \\frac{1}{3o+1} \\quad (\\chi \\ne \\mathbf 1), \\]\nset\n\\[ \\mathcal G_\\psi(x) = \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\Re G_\\chi(x) \\qquad (x \\ge 1), \\]\nwhere $G_\\chi$ is the \\hyperref[8JF7]{smoothed prime sum}. This one real function \\hyperref[8JM7]{sees the zeros of every $L(s,\\chi)$ with $\\chi \\in \\mathcal C_\\psi$}; in \\hyperref[7HM3]{the deduction} only the positivity of the weights matters. See the \\hyperref[8JJ5]{example} of the character modulo $4$.","aliases":["weighted-sum"]}', 'claude');
UPDATE results SET statement_tex = 'Let $\psi$ be a \hyperref[8JH4]{primitive character} of \hyperref[8JA9]{order} $o$, and let
\[ \mathcal C_\psi = \left\{ (\psi^j)^* \;\middle|\; j \in \Z,\ 0 \le j < o \right\} \]
be the set of primitive characters \hyperref[8JB2]{inducing} its powers. It contains $\mathbf 1$ and $\psi$ and is closed under $\chi \mapsto \bar\chi$. With the weights
\[ a_{\mathbf 1} = 1, \qquad a_\chi = \frac{1}{3o+1} \quad (\chi \ne \mathbf 1), \]
set
\[ \mathcal G_\psi(x) = \sum_{\chi \in \mathcal C_\psi} a_\chi \Re G_\chi(x) \qquad (x \ge 1), \]
where $G_\chi$ is the \hyperref[8JF7]{smoothed prime sum}. This one real function \hyperref[8JM7]{sees the zeros of every $L(s,\chi)$ with $\chi \in \mathcal C_\psi$}; in \hyperref[7HM3]{the deduction} only the positivity of the weights matters. See the \hyperref[8JJ5]{example} of the character modulo $4$.', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 09:00:00', updated_by = 'claude' WHERE id = 107 AND revision = 1 AND statement_tex = 'Let $\psi$ be a \hyperref[8JH4]{primitive character} of \hyperref[8JA9]{order} $o$, and let
\[ \mathcal C_\psi = \bigl\{ (\psi^j)^* : 0 \le j < o \bigr\} \]
be the set of primitive characters \hyperref[8JB2]{inducing} its powers. It contains $\mathbf 1$ and $\psi$ and is closed under $\chi \mapsto \bar\chi$. With the weights
\[ a_{\mathbf 1} = 1, \qquad a_\chi = \frac{1}{3o+1} \quad (\chi \ne \mathbf 1), \]
set
\[ \mathcal G_\psi(x) = \sum_{\chi \in \mathcal C_\psi} a_\chi \Re G_\chi(x) \qquad (x \ge 1), \]
where $G_\chi$ is the \hyperref[8JF7]{smoothed prime sum}. This one real function \hyperref[8JM7]{sees the zeros of every $L(s,\chi)$ with $\chi \in \mathcal C_\psi$}; in \hyperref[7HM3]{the deduction} only the positivity of the weights matters. See the \hyperref[8JJ5]{example} of the character modulo $4$.';
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '107', 2, 'set-notation-2026-11-24', '{"tag":"8JG8","type":"definition","title":"Cyclic family and weighted sum","section_id":102,"position":2,"listed":1,"statement_tex":"Let $\\psi$ be a \\hyperref[8JH4]{primitive character} of \\hyperref[8JA9]{order} $o$, and let\n\\[ \\mathcal C_\\psi = \\left\\{ (\\psi^j)^* \\;\\middle|\\; j \\in \\Z,\\ 0 \\le j < o \\right\\} \\]\nbe the set of primitive characters \\hyperref[8JB2]{inducing} its powers. It contains $\\mathbf 1$ and $\\psi$ and is closed under $\\chi \\mapsto \\bar\\chi$. With the weights\n\\[ a_{\\mathbf 1} = 1, \\qquad a_\\chi = \\frac{1}{3o+1} \\quad (\\chi \\ne \\mathbf 1), \\]\nset\n\\[ \\mathcal G_\\psi(x) = \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\Re G_\\chi(x) \\qquad (x \\ge 1), \\]\nwhere $G_\\chi$ is the \\hyperref[8JF7]{smoothed prime sum}. This one real function \\hyperref[8JM7]{sees the zeros of every $L(s,\\chi)$ with $\\chi \\in \\mathcal C_\\psi$}; in \\hyperref[7HM3]{the deduction} only the positivity of the weights matters. See the \\hyperref[8JJ5]{example} of the character modulo $4$.","aliases":["weighted-sum"]}', 'claude');

-- result 8JN4 (id 111): \bigl\{ \rho : \Re\rho > 0,\ L(\rho, \chi) = 0 \text{ for some } \chi \in \mathcal C_\psi \bigr\}  ->  \left\{ \rho \in \C \;\middle|\; \Re\rho > 0,\ L(\rho, \chi) = 0 \text{ for some } \chi \in \mathcal C_\psi \right\}
INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '111', 1, 'set-notation-2026-11-24', '{"tag":"8JN4","type":"lemma","title":"Mellin transform and positive residues","section_id":104,"position":1,"listed":1,"statement_tex":"Let $\\mathcal G_\\psi$ be the \\hyperref[8JG8]{weighted sum} and, for $\\Re s > 1$,\n\\[ \\Phi_\\psi(s) = \\int_1^\\infty \\mathcal G_\\psi(x)\\, x^{-s-1}\\, dx. \\]\nLet\n\\[ Z = \\bigl\\{ \\rho : \\Re\\rho > 0,\\ L(\\rho, \\chi) = 0 \\text{ for some } \\chi \\in \\mathcal C_\\psi \\bigr\\}, \\]\na locally finite set, closed under conjugation since $\\mathcal C_\\psi$ is, and let $m_\\chi(\\rho) \\ge 0$ be the multiplicity of $\\rho$ as a zero of $L(s,\\chi)$. Then $\\Phi_\\psi$ continues meromorphically to $\\Re s > 0$, its poles there are exactly the points of $Z$, and each is simple with\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi = -\\frac{S_\\rho}{\\rho(\\rho-1)}, \\qquad S_\\rho = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(m_\\chi(\\rho) + m_{\\bar\\chi}(\\rho)\\bigr) > 0. \\]\nIn particular every real $\\rho \\in Z$ lies in $(0,1)$ and has a positive residue.","aliases":["mellin-poles"]}', 'claude');
UPDATE results SET statement_tex = 'Let $\mathcal G_\psi$ be the \hyperref[8JG8]{weighted sum} and, for $\Re s > 1$,
\[ \Phi_\psi(s) = \int_1^\infty \mathcal G_\psi(x)\, x^{-s-1}\, dx. \]
Let
\[ Z = \left\{ \rho \in \C \;\middle|\; \Re\rho > 0,\ L(\rho, \chi) = 0 \text{ for some } \chi \in \mathcal C_\psi \right\}, \]
a locally finite set, closed under conjugation since $\mathcal C_\psi$ is, and let $m_\chi(\rho) \ge 0$ be the multiplicity of $\rho$ as a zero of $L(s,\chi)$. Then $\Phi_\psi$ continues meromorphically to $\Re s > 0$, its poles there are exactly the points of $Z$, and each is simple with
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = -\frac{S_\rho}{\rho(\rho-1)}, \qquad S_\rho = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi \bigl(m_\chi(\rho) + m_{\bar\chi}(\rho)\bigr) > 0. \]
In particular every real $\rho \in Z$ lies in $(0,1)$ and has a positive residue.', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 09:00:00', updated_by = 'claude' WHERE id = 111 AND revision = 1 AND statement_tex = 'Let $\mathcal G_\psi$ be the \hyperref[8JG8]{weighted sum} and, for $\Re s > 1$,
\[ \Phi_\psi(s) = \int_1^\infty \mathcal G_\psi(x)\, x^{-s-1}\, dx. \]
Let
\[ Z = \bigl\{ \rho : \Re\rho > 0,\ L(\rho, \chi) = 0 \text{ for some } \chi \in \mathcal C_\psi \bigr\}, \]
a locally finite set, closed under conjugation since $\mathcal C_\psi$ is, and let $m_\chi(\rho) \ge 0$ be the multiplicity of $\rho$ as a zero of $L(s,\chi)$. Then $\Phi_\psi$ continues meromorphically to $\Re s > 0$, its poles there are exactly the points of $Z$, and each is simple with
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = -\frac{S_\rho}{\rho(\rho-1)}, \qquad S_\rho = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi \bigl(m_\chi(\rho) + m_{\bar\chi}(\rho)\bigr) > 0. \]
In particular every real $\rho \in Z$ lies in $(0,1)$ and has a positive residue.';
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '111', 2, 'set-notation-2026-11-24', '{"tag":"8JN4","type":"lemma","title":"Mellin transform and positive residues","section_id":104,"position":1,"listed":1,"statement_tex":"Let $\\mathcal G_\\psi$ be the \\hyperref[8JG8]{weighted sum} and, for $\\Re s > 1$,\n\\[ \\Phi_\\psi(s) = \\int_1^\\infty \\mathcal G_\\psi(x)\\, x^{-s-1}\\, dx. \\]\nLet\n\\[ Z = \\left\\{ \\rho \\in \\C \\;\\middle|\\; \\Re\\rho > 0,\\ L(\\rho, \\chi) = 0 \\text{ for some } \\chi \\in \\mathcal C_\\psi \\right\\}, \\]\na locally finite set, closed under conjugation since $\\mathcal C_\\psi$ is, and let $m_\\chi(\\rho) \\ge 0$ be the multiplicity of $\\rho$ as a zero of $L(s,\\chi)$. Then $\\Phi_\\psi$ continues meromorphically to $\\Re s > 0$, its poles there are exactly the points of $Z$, and each is simple with\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi = -\\frac{S_\\rho}{\\rho(\\rho-1)}, \\qquad S_\\rho = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(m_\\chi(\\rho) + m_{\\bar\\chi}(\\rho)\\bigr) > 0. \\]\nIn particular every real $\\rho \\in Z$ lies in $(0,1)$ and has a positive residue.","aliases":["mellin-poles"]}', 'claude');

-- proof 8JP5 (id 102): \{\Re s > 0\}  ->  \left\{ s \in \C \;\middle|\; \Re s > 0 \right\}
INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '102', 1, 'set-notation-2026-11-24', '{"result_id":113,"status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1,"body_tex":"\\emph{A one-sided bound.} Put $g(u) = \\mathcal G_\\psi(e^u)$. Then $g$ is real, $|g(u)| \\le C_\\psi e^{2u}$, and\n\\[ \\Phi_\\psi(s) = \\int_0^\\infty g(u) e^{-su}\\,du. \\]\nFix $\\sigma = 336$ and, for $k \\ge 0$, set\n\\[ K_k(u) = \\frac{u^k e^{-\\sigma u}}{k!} \\ge 0, \\qquad A_k(s) = \\frac{(-1)^k}{k!}\\Phi_\\psi^{(k)}(s), \\qquad\\text{so}\\qquad A_k(\\sigma + i\\tau) = \\int_0^\\infty g(u) K_k(u) e^{-i\\tau u}\\,du. \\]\nSince $|g| + g = 2g_+$ with $g_+ = \\max(g, 0)$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le 2\\int_0^\\infty g_+(u) K_k(u)\\,du \\qquad (\\tau \\in \\R). \\]\nSo only an \\emph{upper} bound for $g$ is needed. Take $Y$ from the hypothesis, and\n\\[ U = \\log Y, \\qquad k = \\lceil 420U \\rceil. \\]\nThe kernel $K_k$ peaks at $u = k/\\sigma \\approx \\frac54 U$, inside $[U, \\frac32 U]$, where $g_+(u) \\le e^{\\theta u}$. That range contributes at most\n\\[ \\int_0^\\infty e^{\\theta u} K_k(u)\\,du = (\\sigma - \\theta)^{-k-1}. \\]\nOn the tails use $g_+ \\le C_\\psi e^{2u}$; a direct computation bounds them by $O_\\psi(336^{-k})$. With $D_* = \\sigma - \\theta$ we get, for an unbounded sequence of $k$ and uniformly in $\\tau$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C_* D_*^{-k}. \\tag{$*$} \\]\n\n\\emph{Cauchy''s estimate.} If $\\rho$ is the only pole of $\\Phi_\\psi$ in a closed disk $\\overline B(z, r) \\subset \\{\\Re s > 0\\}$, with residue $c$, then, with a constant independent of $k$,\n\\[ A_k(z) = \\frac{c}{(z - \\rho)^{k+1}} + O(r^{-k}). \\]\n\n\\emph{Contradiction.} Suppose some $\\rho_0 \\in Z$ has $\\Re \\rho_0 > \\theta$. Let\n\\[ D = \\min\\bigl(D_*, \\operatorname{dist}(\\sigma, Z)\\bigr), \\]\nso the disk $B(\\sigma, D)$ contains no pole.\n\n(a) Some pole $\\rho_1$ has $\\sigma - \\Re\\rho_1 < D$. For $\\tau$ near $\\Im \\rho_1$, a disk about $z = \\sigma + i\\tau$ of fixed radius less than $D$ contains $\\rho_1$, and for $\\tau$ in a short interval these disks meet only finitely many poles. Two poles with different imaginary parts are equidistant from $z$ for at most one $\\tau$; two with equal imaginary parts never are, as both lie left of $\\Re s = \\sigma$. Avoiding these finitely many $\\tau$, $z$ has a unique nearest pole $\\rho$, at distance $d < D$. Choose $d < r < D$ with $\\rho$ the only pole in $\\overline B(z, r)$. Since $\\overline B(\\sigma, r)$ has no pole and the residue $c$ is nonzero by \\hyperref[8JN4]{the lemma},\n\\[ |A_k(z)| + \\Re A_k(\\sigma) \\ge |c|\\, d^{-k-1} - O(r^{-k}). \\]\nMultiplying $(*)$ by $d^k$ and letting $k \\to \\infty$ gives $|c|/d \\le 0$.\n\n(b) Every pole has $\\sigma - \\Re\\rho \\ge D$. Applied to $\\rho_0$ this gives $D \\le \\sigma - \\Re\\rho_0 < D_*$, so $D = \\operatorname{dist}(\\sigma, Z)$, attained (as $Z$ is locally finite) at some $\\rho$ with\n\\[ |\\sigma - \\rho| = D \\le \\sigma - \\Re\\rho. \\]\nHence $\\rho = \\beta = \\sigma - D$ is real and the unique nearest pole, with residue $c_\\beta > 0$ by \\hyperref[8JN4]{the lemma}. For some $D < r < D_*$,\n\\[ \\Re A_k(\\sigma) = c_\\beta D^{-k-1} + O(r^{-k}), \\]\nwhile $(*)$ with $\\tau = 0$ gives $2\\Re A_k(\\sigma) \\le C_* D_*^{-k}$. Multiplying by $D^k$ gives $c_\\beta / D \\le 0$.\n\nBoth cases are impossible, so $\\Re\\rho \\le \\theta$ for all $\\rho \\in Z$. The positivity of the residue at real poles is what lets a \\emph{one-sided} bound exclude real zeros."}', '(before history)');
UPDATE proofs SET body_tex = '\emph{A one-sided bound.} Put $g(u) = \mathcal G_\psi(e^u)$. Then $g$ is real, $|g(u)| \le C_\psi e^{2u}$, and
\[ \Phi_\psi(s) = \int_0^\infty g(u) e^{-su}\,du. \]
Fix $\sigma = 336$ and, for $k \ge 0$, set
\[ K_k(u) = \frac{u^k e^{-\sigma u}}{k!} \ge 0, \qquad A_k(s) = \frac{(-1)^k}{k!}\Phi_\psi^{(k)}(s), \qquad\text{so}\qquad A_k(\sigma + i\tau) = \int_0^\infty g(u) K_k(u) e^{-i\tau u}\,du. \]
Since $|g| + g = 2g_+$ with $g_+ = \max(g, 0)$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le 2\int_0^\infty g_+(u) K_k(u)\,du \qquad (\tau \in \R). \]
So only an \emph{upper} bound for $g$ is needed. Take $Y$ from the hypothesis, and
\[ U = \log Y, \qquad k = \lceil 420U \rceil. \]
The kernel $K_k$ peaks at $u = k/\sigma \approx \frac54 U$, inside $[U, \frac32 U]$, where $g_+(u) \le e^{\theta u}$. That range contributes at most
\[ \int_0^\infty e^{\theta u} K_k(u)\,du = (\sigma - \theta)^{-k-1}. \]
On the tails use $g_+ \le C_\psi e^{2u}$; a direct computation bounds them by $O_\psi(336^{-k})$. With $D_* = \sigma - \theta$ we get, for an unbounded sequence of $k$ and uniformly in $\tau$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C_* D_*^{-k}. \tag{$*$} \]

\emph{Cauchy''s estimate.} If $\rho$ is the only pole of $\Phi_\psi$ in a closed disk $\overline B(z, r) \subset \left\{ s \in \C \;\middle|\; \Re s > 0 \right\}$, with residue $c$, then, with a constant independent of $k$,
\[ A_k(z) = \frac{c}{(z - \rho)^{k+1}} + O(r^{-k}). \]

\emph{Contradiction.} Suppose some $\rho_0 \in Z$ has $\Re \rho_0 > \theta$. Let
\[ D = \min\bigl(D_*, \operatorname{dist}(\sigma, Z)\bigr), \]
so the disk $B(\sigma, D)$ contains no pole.

(a) Some pole $\rho_1$ has $\sigma - \Re\rho_1 < D$. For $\tau$ near $\Im \rho_1$, a disk about $z = \sigma + i\tau$ of fixed radius less than $D$ contains $\rho_1$, and for $\tau$ in a short interval these disks meet only finitely many poles. Two poles with different imaginary parts are equidistant from $z$ for at most one $\tau$; two with equal imaginary parts never are, as both lie left of $\Re s = \sigma$. Avoiding these finitely many $\tau$, $z$ has a unique nearest pole $\rho$, at distance $d < D$. Choose $d < r < D$ with $\rho$ the only pole in $\overline B(z, r)$. Since $\overline B(\sigma, r)$ has no pole and the residue $c$ is nonzero by \hyperref[8JN4]{the lemma},
\[ |A_k(z)| + \Re A_k(\sigma) \ge |c|\, d^{-k-1} - O(r^{-k}). \]
Multiplying $(*)$ by $d^k$ and letting $k \to \infty$ gives $|c|/d \le 0$.

(b) Every pole has $\sigma - \Re\rho \ge D$. Applied to $\rho_0$ this gives $D \le \sigma - \Re\rho_0 < D_*$, so $D = \operatorname{dist}(\sigma, Z)$, attained (as $Z$ is locally finite) at some $\rho$ with
\[ |\sigma - \rho| = D \le \sigma - \Re\rho. \]
Hence $\rho = \beta = \sigma - D$ is real and the unique nearest pole, with residue $c_\beta > 0$ by \hyperref[8JN4]{the lemma}. For some $D < r < D_*$,
\[ \Re A_k(\sigma) = c_\beta D^{-k-1} + O(r^{-k}), \]
while $(*)$ with $\tau = 0$ gives $2\Re A_k(\sigma) \le C_* D_*^{-k}$. Multiplying by $D^k$ gives $c_\beta / D \le 0$.

Both cases are impossible, so $\Re\rho \le \theta$ for all $\rho \in Z$. The positivity of the residue at real poles is what lets a \emph{one-sided} bound exclude real zeros.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 09:00:00', updated_by = 'claude' WHERE id = 102 AND revision = 1 AND body_tex = '\emph{A one-sided bound.} Put $g(u) = \mathcal G_\psi(e^u)$. Then $g$ is real, $|g(u)| \le C_\psi e^{2u}$, and
\[ \Phi_\psi(s) = \int_0^\infty g(u) e^{-su}\,du. \]
Fix $\sigma = 336$ and, for $k \ge 0$, set
\[ K_k(u) = \frac{u^k e^{-\sigma u}}{k!} \ge 0, \qquad A_k(s) = \frac{(-1)^k}{k!}\Phi_\psi^{(k)}(s), \qquad\text{so}\qquad A_k(\sigma + i\tau) = \int_0^\infty g(u) K_k(u) e^{-i\tau u}\,du. \]
Since $|g| + g = 2g_+$ with $g_+ = \max(g, 0)$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le 2\int_0^\infty g_+(u) K_k(u)\,du \qquad (\tau \in \R). \]
So only an \emph{upper} bound for $g$ is needed. Take $Y$ from the hypothesis, and
\[ U = \log Y, \qquad k = \lceil 420U \rceil. \]
The kernel $K_k$ peaks at $u = k/\sigma \approx \frac54 U$, inside $[U, \frac32 U]$, where $g_+(u) \le e^{\theta u}$. That range contributes at most
\[ \int_0^\infty e^{\theta u} K_k(u)\,du = (\sigma - \theta)^{-k-1}. \]
On the tails use $g_+ \le C_\psi e^{2u}$; a direct computation bounds them by $O_\psi(336^{-k})$. With $D_* = \sigma - \theta$ we get, for an unbounded sequence of $k$ and uniformly in $\tau$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C_* D_*^{-k}. \tag{$*$} \]

\emph{Cauchy''s estimate.} If $\rho$ is the only pole of $\Phi_\psi$ in a closed disk $\overline B(z, r) \subset \{\Re s > 0\}$, with residue $c$, then, with a constant independent of $k$,
\[ A_k(z) = \frac{c}{(z - \rho)^{k+1}} + O(r^{-k}). \]

\emph{Contradiction.} Suppose some $\rho_0 \in Z$ has $\Re \rho_0 > \theta$. Let
\[ D = \min\bigl(D_*, \operatorname{dist}(\sigma, Z)\bigr), \]
so the disk $B(\sigma, D)$ contains no pole.

(a) Some pole $\rho_1$ has $\sigma - \Re\rho_1 < D$. For $\tau$ near $\Im \rho_1$, a disk about $z = \sigma + i\tau$ of fixed radius less than $D$ contains $\rho_1$, and for $\tau$ in a short interval these disks meet only finitely many poles. Two poles with different imaginary parts are equidistant from $z$ for at most one $\tau$; two with equal imaginary parts never are, as both lie left of $\Re s = \sigma$. Avoiding these finitely many $\tau$, $z$ has a unique nearest pole $\rho$, at distance $d < D$. Choose $d < r < D$ with $\rho$ the only pole in $\overline B(z, r)$. Since $\overline B(\sigma, r)$ has no pole and the residue $c$ is nonzero by \hyperref[8JN4]{the lemma},
\[ |A_k(z)| + \Re A_k(\sigma) \ge |c|\, d^{-k-1} - O(r^{-k}). \]
Multiplying $(*)$ by $d^k$ and letting $k \to \infty$ gives $|c|/d \le 0$.

(b) Every pole has $\sigma - \Re\rho \ge D$. Applied to $\rho_0$ this gives $D \le \sigma - \Re\rho_0 < D_*$, so $D = \operatorname{dist}(\sigma, Z)$, attained (as $Z$ is locally finite) at some $\rho$ with
\[ |\sigma - \rho| = D \le \sigma - \Re\rho. \]
Hence $\rho = \beta = \sigma - D$ is real and the unique nearest pole, with residue $c_\beta > 0$ by \hyperref[8JN4]{the lemma}. For some $D < r < D_*$,
\[ \Re A_k(\sigma) = c_\beta D^{-k-1} + O(r^{-k}), \]
while $(*)$ with $\tau = 0$ gives $2\Re A_k(\sigma) \le C_* D_*^{-k}$. Multiplying by $D^k$ gives $c_\beta / D \le 0$.

Both cases are impossible, so $\Re\rho \le \theta$ for all $\rho \in Z$. The positivity of the residue at real poles is what lets a \emph{one-sided} bound exclude real zeros.';
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '102', 2, 'set-notation-2026-11-24', '{"result_id":113,"status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1,"body_tex":"\\emph{A one-sided bound.} Put $g(u) = \\mathcal G_\\psi(e^u)$. Then $g$ is real, $|g(u)| \\le C_\\psi e^{2u}$, and\n\\[ \\Phi_\\psi(s) = \\int_0^\\infty g(u) e^{-su}\\,du. \\]\nFix $\\sigma = 336$ and, for $k \\ge 0$, set\n\\[ K_k(u) = \\frac{u^k e^{-\\sigma u}}{k!} \\ge 0, \\qquad A_k(s) = \\frac{(-1)^k}{k!}\\Phi_\\psi^{(k)}(s), \\qquad\\text{so}\\qquad A_k(\\sigma + i\\tau) = \\int_0^\\infty g(u) K_k(u) e^{-i\\tau u}\\,du. \\]\nSince $|g| + g = 2g_+$ with $g_+ = \\max(g, 0)$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le 2\\int_0^\\infty g_+(u) K_k(u)\\,du \\qquad (\\tau \\in \\R). \\]\nSo only an \\emph{upper} bound for $g$ is needed. Take $Y$ from the hypothesis, and\n\\[ U = \\log Y, \\qquad k = \\lceil 420U \\rceil. \\]\nThe kernel $K_k$ peaks at $u = k/\\sigma \\approx \\frac54 U$, inside $[U, \\frac32 U]$, where $g_+(u) \\le e^{\\theta u}$. That range contributes at most\n\\[ \\int_0^\\infty e^{\\theta u} K_k(u)\\,du = (\\sigma - \\theta)^{-k-1}. \\]\nOn the tails use $g_+ \\le C_\\psi e^{2u}$; a direct computation bounds them by $O_\\psi(336^{-k})$. With $D_* = \\sigma - \\theta$ we get, for an unbounded sequence of $k$ and uniformly in $\\tau$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C_* D_*^{-k}. \\tag{$*$} \\]\n\n\\emph{Cauchy''s estimate.} If $\\rho$ is the only pole of $\\Phi_\\psi$ in a closed disk $\\overline B(z, r) \\subset \\left\\{ s \\in \\C \\;\\middle|\\; \\Re s > 0 \\right\\}$, with residue $c$, then, with a constant independent of $k$,\n\\[ A_k(z) = \\frac{c}{(z - \\rho)^{k+1}} + O(r^{-k}). \\]\n\n\\emph{Contradiction.} Suppose some $\\rho_0 \\in Z$ has $\\Re \\rho_0 > \\theta$. Let\n\\[ D = \\min\\bigl(D_*, \\operatorname{dist}(\\sigma, Z)\\bigr), \\]\nso the disk $B(\\sigma, D)$ contains no pole.\n\n(a) Some pole $\\rho_1$ has $\\sigma - \\Re\\rho_1 < D$. For $\\tau$ near $\\Im \\rho_1$, a disk about $z = \\sigma + i\\tau$ of fixed radius less than $D$ contains $\\rho_1$, and for $\\tau$ in a short interval these disks meet only finitely many poles. Two poles with different imaginary parts are equidistant from $z$ for at most one $\\tau$; two with equal imaginary parts never are, as both lie left of $\\Re s = \\sigma$. Avoiding these finitely many $\\tau$, $z$ has a unique nearest pole $\\rho$, at distance $d < D$. Choose $d < r < D$ with $\\rho$ the only pole in $\\overline B(z, r)$. Since $\\overline B(\\sigma, r)$ has no pole and the residue $c$ is nonzero by \\hyperref[8JN4]{the lemma},\n\\[ |A_k(z)| + \\Re A_k(\\sigma) \\ge |c|\\, d^{-k-1} - O(r^{-k}). \\]\nMultiplying $(*)$ by $d^k$ and letting $k \\to \\infty$ gives $|c|/d \\le 0$.\n\n(b) Every pole has $\\sigma - \\Re\\rho \\ge D$. Applied to $\\rho_0$ this gives $D \\le \\sigma - \\Re\\rho_0 < D_*$, so $D = \\operatorname{dist}(\\sigma, Z)$, attained (as $Z$ is locally finite) at some $\\rho$ with\n\\[ |\\sigma - \\rho| = D \\le \\sigma - \\Re\\rho. \\]\nHence $\\rho = \\beta = \\sigma - D$ is real and the unique nearest pole, with residue $c_\\beta > 0$ by \\hyperref[8JN4]{the lemma}. For some $D < r < D_*$,\n\\[ \\Re A_k(\\sigma) = c_\\beta D^{-k-1} + O(r^{-k}), \\]\nwhile $(*)$ with $\\tau = 0$ gives $2\\Re A_k(\\sigma) \\le C_* D_*^{-k}$. Multiplying by $D^k$ gives $c_\\beta / D \\le 0$.\n\nBoth cases are impossible, so $\\Re\\rho \\le \\theta$ for all $\\rho \\in Z$. The positivity of the residue at real poles is what lets a \\emph{one-sided} bound exclude real zeros."}', 'claude');
